use thiserror::Error;
use crate::abi::*;

#[derive(Error, Debug)]
pub enum JitCompileError {
    #[error("Unsupported type: {0:?}")]
    UnsupportedType(tempra_bytecode::function::BytecodeType),
    
    #[error("Unsupported instruction: {0:?}")]
    UnsupportedInstr(tempra_bytecode::opcode::BytecodeInstr),
    
    #[error("Unsupported function signature (only Int64 params/ret supported)")]
    UnsupportedSignature,
    
    #[error("Cranelift error: {0}")]
    CraneliftError(String),
}

/// Structured errors generated by JIT runtime helpers.
#[derive(Error, Debug, Clone, PartialEq, Eq)]
pub enum JitRuntimeError {
    #[error("Execution error: {0}")]
    Message(String),
    #[error("Invalid context")]
    InvalidContext,
    #[error("Invalid handle")]
    InvalidHandle,
    #[error("Type error")]
    TypeError,
    #[error("Out of bounds")]
    OutOfBounds,
    #[error("Wrong enum variant")]
    WrongVariant,
    #[error("Allocation failed")]
    AllocationFailed,
    #[error("Helper failed with status {status}")]
    HelperFailed { status: i64 },
}

impl JitRuntimeError {
    /// Maps a raw JIT status code to a structured error.
    /// Returns `None` if the status is `JIT_STATUS_SUCCESS`.
    pub fn from_status(status: i64) -> Option<Self> {
        match status {
            JIT_STATUS_SUCCESS => None,
            JIT_STATUS_ERROR_INVALID_CONTEXT => Some(Self::InvalidContext),
            JIT_STATUS_ERROR_INVALID_HANDLE => Some(Self::InvalidHandle),
            JIT_STATUS_ERROR_TYPE => Some(Self::TypeError),
            JIT_STATUS_ERROR_OUT_OF_BOUNDS => Some(Self::OutOfBounds),
            JIT_STATUS_ERROR_WRONG_VARIANT => Some(Self::WrongVariant),
            JIT_STATUS_ERROR_ALLOCATION_FAILED => Some(Self::AllocationFailed),
            _ => Some(Self::HelperFailed { status }),
        }
    }
}

/// Policies for handling JIT runtime failures.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum JitFailurePolicy {
    /// Return the error to the caller at the native wrapper boundary.
    ReturnError,
    /// Issue a native trap/abort (reserved for internal bugs).
    Trap,
    /// Roll back to VM execution (requires deoptimization support).
    FallbackToVm,
}
